18: import { HttpClient } from '@angular/common/http';
19: import { Injectable, inject } from '@angular/core';
20: 
21: import { Observable } from 'rxjs';
22: 
23: import { environment } from '../../../environments/environment';
24: import { HospitalLocation } from '../models/hospital-location';
25: import { NotifierFacilityFormModel } from '../models/bed-occupancy-form-model';
26: import { JwtHelperService } from '@auth0/angular-jwt';
27: 
28: @Injectable({
29:   providedIn: 'root',
30: })
31: export class BedOccupancyStorageService {
32:   private readonly httpClient = inject(HttpClient);
33: 
34:   private readonly jwtHelper = inject(JwtHelperService);
35: 
36:   fetchHospitalLocations(): Observable<HospitalLocation[]> {
37:     const ik = this.getIkNumber();
38:     return this.httpClient.get<HospitalLocation[]>(`${environment.pathToHospitalLocations}?ik=${ik}`, {
39:       headers: environment.headers,
40:     });
41:   }
42: 
43:   getIkNumber(): string {
44:     const jwt = window['token'];
45:     const decodedToken = this.jwtHelper.decodeToken(jwt);
46:     const ik = decodedToken.ik;
47:     // Check if 'ik' matches the regex pattern for 9 digits
48:     const regex = /^\d{9}$/;
49:     if (typeof ik === 'string' && regex.test(ik)) {
50:       return ik;
51:     }
52:     const preferredUsername = decodedToken.preferred_username;
53:     if (!preferredUsername || !preferredUsername.startsWith('5-2-')) {
54:       console.warn(`the preferredUsername '${preferredUsername}' is blank or does not start with '5-2-'`);
55:       return null;
56:     }
57:     try {
58:       return preferredUsername.split('-')[2];
59:     } catch (ex) {
60:       console.warn(`failed to extract ik from preferredUsername ${preferredUsername} - ${ex.message}`);
61:       return null;
62:     }
63:   }
64: 
65:   setLocalStorageBedOccupancyData(ikNumber: string, data: NotifierFacilityFormModel): void {
66:     // Retrieve the existing bed occupancy object from local storage, or initialize a new object if none exists
67:     const bedOccupancy = JSON.parse(localStorage.getItem('bedOccupancy') || '{}');
68: 
69:     // Update the data for the given IK number
70:     bedOccupancy[ikNumber] = data;
71: 
72:     // Save the updated object back to local storage
73:     localStorage.setItem('bedOccupancy', JSON.stringify(bedOccupancy));
74:   }
75: 
76:   getLocalStorageBedOccupancyData(ikNumber: string): NotifierFacilityFormModel | null {
77:     // Retrieve the bed occupancy object from local storage
78:     const bedOccupancy = JSON.parse(localStorage.getItem('bedOccupancy') || '{}');
79: 
80:     // Return the data for the specified IK number, or null if it doesn't exist
81:     return bedOccupancy[ikNumber] || null;
82:   }
83: }

