18: import { HttpClient, HttpErrorResponse, HttpHeaders, HttpResponse } from '@angular/common/http';
19: import { inject, Injectable } from '@angular/core';
20: import { BedOccupancy, OkResponse, ValidationError } from 'src/api/notification';
21: import { NGXLogger } from 'ngx-logger';
22: import { MatDialog } from '@angular/material/dialog';
23: import { ErrorMessage, MessageDialogService, SubmitDialogProps, trimStrings } from '@gematik/demis-portal-core-library';
24: import { environment } from '../../../environments/environment';
25: import { FileService } from './file.service';
26: import { finalize } from 'rxjs/operators';
27: import { BedOccupancyFormModel } from '../models/bed-occupancy-form-model';
28: 
29: @Injectable({
30:   providedIn: 'root',
31: })
32: export class FhirBedOccupancyService {
33:   protected httpClient: HttpClient;
34:   protected logger: NGXLogger;
35:   dialog = inject(MatDialog);
36:   private readonly messageDialogService = inject(MessageDialogService);
37:   private readonly fileService = inject(FileService);
38: 
39:   constructor() {
40:     const httpClient = inject(HttpClient);
41:     const logger = inject(NGXLogger);
42: 
43:     this.httpClient = httpClient;
44:     this.logger = logger;
45:   }
46: 
47:   transformData(originalData: BedOccupancyFormModel): BedOccupancy {
48:     //contacts (backend) is expecting an array and not like the datamodel is provided an object.
49: 
50:     const contacts = originalData.notifierFacility.contacts;
51:     const transformedContacts = Array.isArray(contacts) ? contacts : [...(contacts?.phoneNumbers || []), ...(contacts?.emailAddresses || [])];
52: 
53:     return {
54:       notifierFacility: {
55:         ...originalData.notifierFacility,
56:         contacts: transformedContacts,
57:       },
58:       bedOccupancyQuestion: originalData.bedOccupancyQuestion,
59:     } as BedOccupancy;
60:   }
61: 
62:   submitNotification(notification: BedOccupancy) {
63:     this.messageDialogService.showSpinnerDialog({ message: 'Meldung wird gesendet' });
64: 
65:     const trimmedNotification = trimStrings(notification);
66:     this.httpClient
67:       .post(environment.pathToBedOccupancy, JSON.stringify(trimmedNotification), {
68:         headers: FhirBedOccupancyService.getEnvironmentHeaders(),
69:         observe: 'response',
70:       })
71:       .pipe(
72:         finalize(() => {
73:           this.messageDialogService.closeSpinnerDialog();
74:         })
75:       )
76:       .subscribe({
77:         next: (response: HttpResponse<OkResponse>) => {
78:           const submitDialogData = this.createSubmitDialogData(response, notification);
79:           this.messageDialogService.showSubmitDialog(submitDialogData);
80:         },
81:         error: err => {
82:           this.logger.error('error', err);
83:           const errors = this.extractErrorDetails(err);
84:           this.messageDialogService.showErrorDialog({
85:             errorTitle: 'Meldung konnte nicht zugestellt werden!',
86:             errors,
87:           });
88:         },
89:       });
90:   }
91: 
92:   private createSubmitDialogData(response: HttpResponse<OkResponse>, notification: BedOccupancy): SubmitDialogProps {
93:     const content = encodeURIComponent(response.body.content);
94:     const href = 'data:application/actet-stream;base64,' + content;
95:     return {
96:       authorEmail: response.body.authorEmail,
97:       fileName: this.fileService.getFileNameByNotificationType(notification),
98:       href: href,
99:       notificationId: response.body.notificationId,
100:       timestamp: response.body.timestamp,
101:     };
102:   }
103: 
104:   private extractErrorDetails(err: HttpErrorResponse): ErrorMessage[] {
105:     const response = err?.error ?? err;
106:     const errorMessage = this.messageDialogService.extractMessageFromError(response);
107:     const validationErrors = response?.validationErrors || [];
108: 
109:     if (validationErrors.length > 0) {
110:       return validationErrors.map((ve: ValidationError) => ({
111:         text: ve.message,
112:         queryString: ve.message || '',
113:         severity: ve.severity,
114:       }));
115:     }
116: 
117:     return [
118:       {
119:         text: errorMessage,
120:         queryString: errorMessage || '',
121:       },
122:     ];
123:   }
124: 
125:   private static getEnvironmentHeaders(): HttpHeaders {
126:     return environment.headers;
127:   }
128: }

