121:     //set data to storage
122:     this.bedOccupancyStorageService.setLocalStorageBedOccupancyData(this.IkNumber, {
123:       ...this.model.notifierFacility,
124:     });
125:     this.sendFunction(transformedData);
126:   }
127: 
