82:     this.hospitalLocationsSubscription = this.bedOccupancyStorageService
83:       .fetchHospitalLocations()
84:       .pipe(takeUntil(this.unsubscriber))
85:       .subscribe({
86:         next: (locations: HospitalLocation[]) => {
87:           this.hospitalLocations = locations;
88:           // looking for the IK Number
89:           this.IkNumber = locations[0]?.ik || 'not-provided';
90:           this.fieldConfig = notifierFacilityBedOccupancyFormConfigFields(this.IkNumber, this.hospitalLocations);
91:           //retrieve data from storage
92:           const localStorageData = this.bedOccupancyStorageService.getLocalStorageBedOccupancyData(this.IkNumber);
93:           if (localStorageData !== null && localStorageData !== undefined) {
94:             const loadedData = localStorageData;
95:             const notifierFacilityDataFromLocalStorage: NotifierFacilityFormModel = {
96:               ...loadedData,
97:               address: {
98:                 ...loadedData.address,
99:                 country: 'DE', //DEMIS-1801: overwrite old countryCode from storage
100:               },
101:               contacts: this.stripEmptyContactEntries(loadedData.contacts),
102:             };
103:             this.notificationService.patchFormData({ notifierFacility: notifierFacilityDataFromLocalStorage }, { markAsTouched: false });
104:           } else {
105:             // The FormGroup is pre-built in the service with an empty IK,we need to patch the real IK
106:             this.notificationService.patchFormData({ notifierFacility: { facilityInfo: { ikNumber: this.IkNumber } } }, { markAsTouched: false });
107:           }
108:           // Rebuilding fieldConfig above replaces the rendered controls, discarding any focus SideNavigationComponent
109:           // already set right after this step became visible. Re-focus once Angular has actually rendered the new
110:           // controls, but only if this render was supposed to receive focus (e.g. not on the initial page load).
111:           if (this.autoFocusRequested()) {
112:             afterNextRender(() => this.navigation.getFocusableElements(this.elementRef.nativeElement)[0]?.focus({ preventScroll: true }), {
113:               injector: this.injector,
114:             });
115:           }
116:         },
117:         error: error => {
118:           const errorMessage = this.messageDialogService.extractMessageFromError(error);
119:           this.messageDialogService.showErrorDialog({
120:             redirectToHome: true,
121:             errorTitle: BedOccupancyConstants.ERROR_NO_LOCATIONS_DIALOG,
122:             errors: [
123:               {
124:                 text: errorMessage,
125:               },
126:             ],
127:           });
128:         },
129:       });
130:   }
