132:   ngOnDestroy(): void {
133:     this.unsubscriber.next();
134:     this.unsubscriber.complete();
135: 
136:     // store notifierFacility in localstorage when leaving step 1
137:     const model = this.notificationService.getModelData().notifierFacility;
138:     this.bedOccupancyStorageService.setLocalStorageBedOccupancyData(model.facilityInfo?.ikNumber, {
139:       ...model,
140:       contacts: this.stripEmptyContactEntries(model.contacts),
141:     });
142:   }
