144:   /**
145:    * Removes contact entries whose `value` is empty so that Formly's repeater
146:    * doesn't reinstantiate an empty (but required) row from persisted data.
147:    * Preserves the legacy `ContactPointInfo[]` shape as well as the new
148:    * `{ phoneNumbers, emailAddresses }` shape.
149:    */
150:   private stripEmptyContactEntries(contacts: NotifierFacilityFormModel['contacts']): NotifierFacilityFormModel['contacts'] {
151:     if (!contacts) return contacts;
152: 
153:     const hasValue = (c: Partial<ContactPointInfo> | undefined): c is ContactPointInfo => !!c?.value;
154: 
155:     if (Array.isArray(contacts)) {
156:       return contacts.filter(hasValue);
157:     }
158: 
159:     const { phoneNumbers, emailAddresses } = contacts;
160:     return {
161:       phoneNumbers: (phoneNumbers ?? []).filter(hasValue),
162:       emailAddresses: (emailAddresses ?? []).filter(hasValue),
163:     };
164:   }
165: 
166:   protected readonly BedOccupancyConstants = BedOccupancyConstants;
167: }

